## Event Delegation

### Without Delegation (problematic with dynamic items)
```js
document.querySelectorAll('.item').forEach(item => {
  item.addEventListener('click', handleClick);
});
// newly added items are NOT covered
```

### With Delegation
```js
const list = document.querySelector('#list');

list.addEventListener('click', (event) => {
  const item = event.target.closest('.item');
  if (!item) return; // click was outside an item
  handleClick(item);
});

// Works for items added later:
list.insertAdjacentHTML('beforeend', '<li class="item">New</li>');
```

### Real-World: Delete Button inside Card
```js
document.querySelector('#cards').addEventListener('click', (e) => {
  if (e.target.matches('[data-action="delete"]')) {
    const card = e.target.closest('[data-id]');
    deleteCard(card.dataset.id);
  }
});
```

### Gotchas
- `stopPropagation()` in a child handler will prevent the parent from seeing the event
- `event.target` is the exact element clicked; `event.currentTarget` is the element with the listener
- Use `.closest()` for nested markup (e.g., clicking an icon inside a button)

## Prototypal Inheritance

### The Chain in Action
```js
const animal = {
  breathe() { return 'breathing'; },
};

const dog = Object.create(animal);
dog.bark = function () { return 'woof'; };

const rex = Object.create(dog);

console.log(rex.bark());    // 'woof'    — found on dog
console.log(rex.breathe()); // 'breathing' — found on animal
console.log(rex.toString()); // from Object.prototype
```

### Constructor Functions
```js
function Vehicle(type) {
  this.type = type;
}
Vehicle.prototype.describe = function () {
  return `I am a ${this.type}`;
};

const car = new Vehicle('car');
car.describe(); // 'I am a car'

// car.__proto__ === Vehicle.prototype  ✓
// Vehicle.prototype.__proto__ === Object.prototype  ✓
```

### ES6 Classes (same chain)
```js
class Vehicle {
  constructor(type) { this.type = type; }
  describe() { return `I am a ${this.type}`; }
}
class Car extends Vehicle {
  honk() { return 'beep'; }
}
const c = new Car('car');
// c → Car.prototype → Vehicle.prototype → Object.prototype → null
```

### Own vs Inherited
```js
console.log(car.hasOwnProperty('type'));     // true  — own
console.log(car.hasOwnProperty('describe')); // false — inherited
```

## The `this` Keyword

### 1. Default Binding
```js
function greet() { console.log(this); }
greet(); // window (non-strict) | undefined (strict)
```

### 2. Implicit Binding
```js
const user = {
  name: 'Alice',
  greet() { return this.name; },
};
user.greet(); // 'Alice' — this = user

const fn = user.greet;
fn(); // undefined — lost implicit binding!
```

### 3. Explicit Binding
```js
function greet() { return this.name; }
const user = { name: 'Alice' };

greet.call(user);        // 'Alice'
greet.apply(user);       // 'Alice'
const bound = greet.bind(user);
bound();                 // 'Alice'
```

### 4. new Binding
```js
function Person(name) {
  this.name = name;
}
const p = new Person('Bob');
p.name; // 'Bob' — this = new object
```

### 5. Arrow Function (lexical this)
```js
class Timer {
  constructor() { this.ticks = 0; }
  start() {
    // Arrow function: `this` is the Timer instance
    setInterval(() => { this.ticks++; }, 1000);
    // Regular function would lose `this` context
  }
}
```

### Precedence
`new` > explicit (`bind`/`call`/`apply`) > implicit > default

## Promises

### Creating a Promise
```js
const delay = (ms) =>
  new Promise((resolve) => setTimeout(resolve, ms));

delay(1000).then(() => console.log('1 second passed'));
```

### Chaining
```js
fetch('/api/user')
  .then(res => res.json())
  .then(user => fetch(`/api/posts?userId=${user.id}`))
  .then(res => res.json())
  .then(posts => console.log(posts))
  .catch(err => console.error(err));
```

### Combinators
```js
// All must resolve — rejects on first failure
const [user, posts] = await Promise.all([
  fetchUser(id),
  fetchPosts(id),
]);

// Wait for all, get outcomes regardless
const results = await Promise.allSettled([p1, p2, p3]);
results.forEach(r => {
  if (r.status === 'fulfilled') console.log(r.value);
  else console.error(r.reason);
});

// First to settle (resolve OR reject)
const first = await Promise.race([timeout(5000), fetchData()]);

// First to resolve (ignores rejections)
const fastest = await Promise.any([mirror1, mirror2, mirror3]);
```

### Promise State Machine
```
Pending → Fulfilled (via resolve)
Pending → Rejected  (via reject / throw)
Fulfilled/Rejected → immutable (settled)
```

## async/await

### Basic Usage
```js
async function loadUser(id) {
  try {
    const res = await fetch(`/api/users/${id}`);
    if (!res.ok) throw new Error(`HTTP ${res.status}`);
    return await res.json();
  } catch (err) {
    console.error('Failed to load user:', err);
    throw err;
  }
}
```

### Sequential vs Parallel
```js
// Sequential — 2 round trips back-to-back (slow)
const user  = await fetchUser(id);
const posts = await fetchPosts(id);

// Parallel — both fire at the same time (fast)
const [user, posts] = await Promise.all([
  fetchUser(id),
  fetchPosts(id),
]);
```

### What the Engine Does (simplified)
```js
// async/await roughly compiles to:
function loadUser(id) {
  return fetch(`/api/users/${id}`)
    .then(res => {
      if (!res.ok) throw new Error(`HTTP ${res.status}`);
      return res.json();
    })
    .catch(err => {
      console.error(err);
      throw err;
    });
}
```

### Common Pitfalls
```js
// ❌ Awaiting in a loop — sequential, slow
for (const id of ids) {
  await processItem(id);
}

// ✅ Parallel
await Promise.all(ids.map(id => processItem(id)));
```

## Debounce

### Implementation
```js
function debounce(fn, delay) {
  let timerId;
  return function (...args) {
    clearTimeout(timerId);
    timerId = setTimeout(() => fn.apply(this, args), delay);
  };
}

// Usage
const handleSearch = debounce((query) => {
  fetchResults(query);
}, 300);

input.addEventListener('input', (e) => handleSearch(e.target.value));
```

### With Leading Option
```js
function debounce(fn, delay, { leading = false } = {}) {
  let timerId;
  return function (...args) {
    const shouldCallNow = leading && !timerId;
    clearTimeout(timerId);
    timerId = setTimeout(() => {
      timerId = null;
      if (!leading) fn.apply(this, args);
    }, delay);
    if (shouldCallNow) fn.apply(this, args);
  };
}
```

### React Hook
```js
function useDebounce(value, delay) {
  const [debounced, setDebounced] = useState(value);
  useEffect(() => {
    const id = setTimeout(() => setDebounced(value), delay);
    return () => clearTimeout(id);
  }, [value, delay]);
  return debounced;
}
```

### Debounce vs Throttle
- **Debounce**: waits for activity to *stop*, then fires once
- **Throttle**: fires at most once per interval *regardless* of activity

## Throttle

### Implementation (Timestamp-based)
```js
function throttle(fn, interval) {
  let lastTime = 0;
  return function (...args) {
    const now = Date.now();
    if (now - lastTime >= interval) {
      lastTime = now;
      fn.apply(this, args);
    }
  };
}

const onScroll = throttle(() => {
  updateStickyHeader();
}, 100);

window.addEventListener('scroll', onScroll);
```

### With Leading + Trailing Options
```js
function throttle(fn, interval) {
  let timerId = null;
  let lastRun = 0;

  return function (...args) {
    const now = Date.now();
    const remaining = interval - (now - lastRun);

    if (remaining <= 0) {
      if (timerId) { clearTimeout(timerId); timerId = null; }
      lastRun = now;
      fn.apply(this, args);
    } else if (!timerId) {
      // Trailing edge — fires once after silence
      timerId = setTimeout(() => {
        lastRun = Date.now();
        timerId = null;
        fn.apply(this, args);
      }, remaining);
    }
  };
}
```

### Visual Comparison
```
Calls:    ▏▏▏▏▏▏▏▏▏▏▏▏▏▏▏▏▏▏▏▏▏▏▏▏
Debounce: ________________________▏  (only after silence)
Throttle: ▏_________▏_________▏___   (every N ms)
```

## Memoization

### Basic Implementation
```js
function memoize(fn) {
  const cache = new Map();
  return function (...args) {
    const key = JSON.stringify(args);
    if (cache.has(key)) {
      return cache.get(key);
    }
    const result = fn.apply(this, args);
    cache.set(key, result);
    return result;
  };
}

// Expensive function
const factorial = memoize(function f(n) {
  return n <= 1 ? 1 : n * f(n - 1);
});

factorial(10); // computed
factorial(10); // returned from cache
```

### React useMemo
```js
function ProductList({ products, filter }) {
  const filtered = useMemo(
    () => products.filter(p => p.category === filter),
    [products, filter] // recompute only when these change
  );
  return <List items={filtered} />;
}
```

### Reselect (Redux)
```js
import { createSelector } from 'reselect';

const selectActiveUsers = createSelector(
  state => state.users,
  users => users.filter(u => u.active) // memoized
);
```

### When NOT to Memoize
- Functions that are cheap to run
- Functions with many unique argument combinations (cache grows unbounded)
- When the cached value is never reused
